// Chapter 10 of the book — converted from the HTML edition; generated file.

export const n = 10;
export const num = "10";
export const title = "Source Control از صفر — Ctrl+Shift+G";
export const label = "فصل ۱۰ · Source Control از صفر";
export const part = 0;
export const html = "<p class=\"lead\">خانهٔ روزانهٔ Git در VS Code پنل Source Control است. میانبر ثابت این کتاب Ctrl+Shift+G است. اینجا هر کلیک را به ترتیب می‌نویسیم و برای هر تفاوت («چرا مال من این‌طور است؟») دلیل دقیق می‌آید.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>پنل را با کلیک مشخص باز کنی و بدانی بعد از آن باید چه ببینی</li>\n<li>اگر دکمه یا لیست تو با عکس کتاب یکی نبود، در همان لحظه علت را بدانی</li>\n<li>یک فایل را از Save تا Commit، کلیک‌به‌کلیک، تمام کنی</li>\n<li>Stage، Unstage، Discard و Stage Selected Ranges را بدون حدس بزنی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧭 قبل از اولین کلیک — عکس کتاب مال <em>یک</em> حالت است</span></span></h2>\n<p class=\"keep-next\">عکس‌های این فصل از یک VS Code واقعی‌اند: ویندوز، زبان انگلیسی، تم تیره، مخزنی که Working Tree تمیز است و origin پانزده کامیت جلوتر. <strong>صفحهٔ تو باید دکمه‌های همان‌جا را داشته باشد، نه لزوماً همان عدد ۱۵ یا همان نام فایل.</strong></p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>چیزی که در عکس می‌بینی</th>\n<th>مال تو ممکن است</th>\n<th>چرا؟</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>برچسب انگلیسی <code>Source Control</code>، <code>Commit</code>، <code>Sync Changes</code></td>\n<td>فارسی: «کنترل منبع»، «ثبت»، «همگام‌سازی تغییرات»</td>\n<td>زبان نمایش VS Code. موقعیت دکمه یکی است؛ فقط نوشته عوض می‌شود.</td>\n</tr>\n<tr>\n<td>تم تیرهٔ سرمه‌ای</td>\n<td>تم روشن یا تم دیگر</td>\n<td>رنگ عوض می‌شود؛ نام فرمان‌ها عوض نمی‌شود.</td>\n</tr>\n<tr>\n<td><code>Sync Changes 15↓</code></td>\n<td><code>Commit</code> یا <code>Publish Branch</code> یا هیچ دکمهٔ آبی</td>\n<td>بستگی دارد تغییرات محلی داری یا نه، و آیا <code>origin</code> هست یا نه — پایین، سه حالت.</td>\n</tr>\n<tr>\n<td>حرف <code>M</code> کنار <code>src/auth.ts</code></td>\n<td>فایل و حرف دیگر، یا لیست خالی</td>\n<td>مثال کتاب است. تو فایل خودت را می‌بینی.</td>\n</tr>\n<tr>\n<td>Graph پایین پنل</td>\n<td>Graph نیست</td>\n<td>نسخهٔ قدیمی VS Code، یا بخش جمع شده؛ فلش <code>&gt;</code> را باز کن.</td>\n</tr>\n<tr>\n<td>میانبر <code>Ctrl+Shift+G</code></td>\n<td>در مک گاهی باید <code>Cmd</code> نباشد؛ همین Ctrl است</td>\n<td>در VS Code روی مک هم پیش‌فرض Ctrl+Shift+G است نه Cmd.</td>\n</tr>\n</tbody>\n</table></div><div class=\"callout callout-note\"><div class=\"callout-title\">زبان عکس‌ها انگلیسی است عمداً</div>\n<p>در شکل‌ها متن فارسی نمی‌گذاریم (برعکس می‌شود). اگر VS Code تو فارسی است، همان دکمه را از روی <em>جایگاه</em> پیدا کن نه از روی املای کتاب.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">⌨️ باز کردن پنل — سه کلیک معادل، یکی کافی است</span></span></h2>\n<p class=\"keep-next\">یکی از این سه را بزن؛ هر سه باید <strong>همان ستون چپ</strong> را باز کنند:</p>\n<ol>\n<li>صفحه کلید: <code>Ctrl+Shift+G</code> (ویندوز، لینوکس، مک)</li>\n<li>ماوس: در نوار باریک چپ (Activity Bar) روی آیکون شاخه/Git کلیک کن — در عکس کتاب شمارهٔ ۱</li>\n<li>اگر هیچ‌کدام کار نکرد: <code>Ctrl+Shift+P</code> → تایپ کن <code>View: Show Source Control</code> → Enter</li>\n</ol>\n<p><strong>بعد از باز شدن باید ببینی:</strong> ستون سمت چپ با عنوان Source Control. ادیتور سمت راست سر جایش می‌ماند.</p>\n<p class=\"keep-next\"><strong>اگر مال تو این‌طور نیست:</strong></p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>چه دیدی</th>\n<th>علت</th>\n<th>چه کار کن</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>هیچ پنلی باز نشد</td>\n<td>فوکوس روی ترمینال است و میانبر قورت داده شد</td>\n<td>یک‌بار روی ادیتور کلیک کن، دوباره <code>Ctrl+Shift+G</code></td>\n</tr>\n<tr>\n<td>پنل Explorer باز شد نه Git</td>\n<td>آیکون اشتباه (دو سند بالا)</td>\n<td>آیکون سوم/چهارم Activity Bar؛ یا همان Palette</td>\n</tr>\n<tr>\n<td>ستون آمد ولی نوشته Git not found / Git not installed</td>\n<td>VS Code فایل <code>git.exe</code> را پیدا نکرده</td>\n<td>Palette → <code>Git: Show Git Output</code>. Settings → <code>git.path</code> را به مسیر نصب Git بده. از نو VS Code را باز کن</td>\n</tr>\n<tr>\n<td>ستون آمد، کاملاً خالی، بدون Message</td>\n<td>پوشه باز نیست</td>\n<td><code>File → Open Folder</code> روی پوشهٔ پروژه</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">🧭 آناتومی — بعد از باز شدن، این چهار نقطه را لمس کن</span></span></h2>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-anatomy.png\" alt=\"آناتومی نزدیک پنل Source Control\"/>\n<p class=\"figcap\">شکل ۹ — برش نزدیک. شماره‌ها را با فهرست زیر تطبیق بده. دکمهٔ آبی اینجا Sync است نه Commit؛ برای تو ممکن است برعکس باشد.</p>\n</div>\n<ol class=\"legend\">\n<li><strong>کلیک روی آیکون Git</strong> در Activity Bar. اگر روی آیکون <em>عدد</em> بود یعنی فایل تغییرکرده داری. اگر عدد نبود، یا Working Tree تمیز است یا نشان روی آیکون دیگری است (در عکس کامل کتاب، نشان آبی روی Extensions است نه Git — این باگ نیست).</li>\n<li><strong>عنوان Source Control</strong> و سه‌نقطهٔ <code>···</code> بالا-راست. یک کلیک روی <code>···</code> منوی Fetch / Pull / Push / Stash را باز می‌کند (فصل ۱۱).</li>\n<li><strong>یک کلیک داخل جعبهٔ Message</strong> — مکان‌نما باید چشمک بزند. این‌جا متن کامیت را می‌نویسی. <code>Ctrl+Enter</code> فقط وقتی کار می‌کند که فوکوس همین جعبه باشد.</li>\n<li><strong>دکمهٔ بزرگ زیر جعبه</strong> — برچسبش <em>ثابت نیست</em>. VS Code بر اساس وضعیت مخزن یکی از این‌ها را می‌نویسد: <strong>Initialize Repository</strong>، <strong>Publish Branch</strong>، <strong>Commit</strong>، <strong>Sync Changes</strong>، یا <strong>Commit (merge)</strong>.</li>\n</ol>\n<p class=\"keep-next\">پایین همان ستون، بدون عوض کردن پنل:</p>\n<ul>\n<li><strong>Graph</strong> — یک کلیک روی <code>&gt;</code> یا روی کلمهٔ Graph. اگر نبود، VS Code را به‌روز کن یا Palette → <code>Git: View History</code>.</li>\n<li class=\"keep-next\"><strong>نوار وضعیت پایین-چپ پنجره</strong> (نه داخل ستون): نام شاخه. <strong>یک کلیک</strong> روی نام شاخه = فهرست عوض کردن شاخه.</li>\n</ul>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-status-zoom.png\" alt=\"نوار وضعیت Git در VS Code\"/>\n<p class=\"figcap\">شکل ۹ب — یک کلیک روی main. عدد ↓ و ↑ مال این مخزن است؛ مال تو ۰ و ۰ هم طبیعی است.</p>\n</div>\n<p><strong>اگر نوار وضعیت شاخه نشان نمی‌دهد:</strong> یا پوشه Git ندارد، یا Git پیدا نشده. اول همان جدول «اگر مال تو این‌طور نیست» را بالا ببین.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">😶 دکمهٔ بزرگ زیر Message — از روی برچسب بفهم کجایی</span></span></h2>\n<p>VS Code یک دکمهٔ اصلی دارد. برچسب را بخوان؛ حدس نزن.</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">حالت ۱ — نوشته Initialize Repository / Publish to GitHub</span></span></h3>\n<p class=\"keep-next\">یعنی پوشه‌ای که <strong>Open Folder</strong> کرده‌ای فایل <code>.git</code> ندارد.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-init-zoom.png\" alt=\"Initialize Repository در Source Control\"/>\n<p class=\"figcap\">شکل ۹پ — فقط وقتی `.git` نیست این دو دکمه را می‌بینی.</p>\n</div>\n<p><strong>کلیک‌ها:</strong></p>\n<ol>\n<li><code>File → Open Folder</code> — پوشهٔ خود پروژه را انتخاب کن، نه درایو و نه پوشهٔ والد.</li>\n<li><code>Ctrl+Shift+G</code>.</li>\n<li><strong>یک کلیک</strong> روی <strong>Initialize Repository</strong>. معادل <code>git init</code>. بعد از کلیک باید جعبهٔ Message ظاهر شود و اگر فایلی باشد، لیست Changes پر شود.</li>\n<li>همان لحظه فایل <code>.gitignore</code> بساز (<code>Ctrl+N</code>، ذخیره با همین نام) تا <code>node_modules</code> در Changes نیاید.</li>\n<li><strong>Publish to GitHub</strong> را فقط اگر می‌خواهی ریپو روی GitHub ساخته شود بزن. اگر بزنی و وارد حساب نباشی، پنجرهٔ ورود مرورگر باز می‌شود — این خطا نیست.</li>\n</ol>\n<p><strong>اگر بعد از Initialize هنوز همان دو دکمه را می‌بینی:</strong> پوشهٔ اشتباه باز است. در Explorer باید <code>.git</code> را (گاهی مخفی) ببینی. <code>File → Open Folder</code> را تکرار کن.</p>\n<p><strong>اگر Publish خاکستری است یا خطا می‌دهد:</strong> Accounts پایین Activity Bar → Sign in to GitHub. بدون ورود، Publish کار نمی‌کند؛ Initialize کار می‌کند.</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">حالت ۲ — نوشته Sync Changes (شاید با عدد ↓ یا ↑)</span></span></h3>\n<p>یعنی مخزن هست، <strong>فایل ذخیره‌شدهٔ تغییرکرده برای کامیت نداری</strong>، ولی با <code>origin</code> هم‌تراز نیستی.</p>\n<ul>\n<li><code>۱۵↓</code> = روی سرور ۱۵ کامیت هست که تو نداری → Sync تقریباً <code>pull</code> است.</li>\n<li><code>↑۳</code> = تو ۳ کامیت داری که سرور ندارد → Sync تقریباً <code>push</code> است.</li>\n<li>هر دو = واگرایی؛ Sync ممکن است merge بسازد.</li>\n</ul>\n<p>لیست Changes خالی در این حالت <strong>موفقیت</strong> است (<code>nothing to commit, working tree clean</code>)، نه اینکه Git خراب باشد.</p>\n<p><strong>اگر Sync را زدی و از تو تأیید خواست:</strong> تنظیم <code>git.confirmSync</code> روشن است — Yes بگو یا در Settings خاموشش کن.</p>\n<p><strong>اگر Sync خطا داد (rejected / diverged):</strong> فصل ۱۱ — اول Fetch، بعد Pull یا Pull (Rebase). Force نزن.</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">حالت ۳ — نوشته Commit (یا Commit با فلش ▾)</span></span></h3>\n<p>یعنی حداقل یک فایل در Changes یا Staged هست.</p>\n<p><strong>اگر تو Commit می‌بینی و کتاب Sync:</strong> تو فایل ذخیره‌نشده یا تغییرکرده داری؛ کتاب در آن عکس Working Tree تمیز نشان می‌دهد. هر دو درست‌اند.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">✍️ مسیر کامل کامیت — کلیک به کلیک</span></span></h2>\n<p class=\"keep-next\">هدف: یک فایل را عوض کنی و در تاریخچه ثبت شود.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-commit-zoom.png\" alt=\"کامیت و diff در Source Control\"/>\n<p class=\"figcap\">شکل ۱۰ — بعد از مرحلهٔ ۴ باید چیزی شبیه این ببینی: پیام، فایل‌ها با M/U، diff سبز/قرمز.</p>\n</div>\n<ol>\n<li>\n<p><strong>فایل را در ادیتور عوض کن</strong> و <code>Ctrl+S</code> بزن.<br />\n<strong>باید ببینی:</strong> روی آیکون Git عدد می‌آید؛ فایل در Changes ظاهر می‌شود.<br />\n<strong>اگر نیامد:</strong> Save نشده، یا فایل داخل <code>.gitignore</code> است، یا پوشهٔ دیگری Open است.</p>\n</li>\n<li>\n<p><strong><code>Ctrl+Shift+G</code>.</strong><br />\n<strong>باید ببینی:</strong> نام فایل + حرف <code>M</code> یا <code>U</code>.</p>\n</li>\n<li>\n<p><strong>یک کلیک روی نام فایل در Changes.</strong><br />\n<strong>باید ببینی:</strong> سمت راست، diff. خط قرمز = حذف، سبز = اضافه.<br />\n<strong>اگر سمت راست همان Welcome VS Code ماند:</strong> روی نام فایل کلیک نشده؛ روی فضای خالی ستون کلیک کرده‌ای.</p>\n</li>\n<li>\n<p><strong>یک کلیک روی <code>+</code> سمت راست همان فایل</strong> (وقتی نشانگر روی ردیف است ظاهر می‌شود). معادل <code>git add</code>.<br />\n<strong>باید ببینی:</strong> فایل از <strong>Changes</strong> به <strong>Staged Changes</strong> می‌پرد.<br />\n<strong>اگر <code>+</code> نبود:</strong> نشانگر را روی ردیف فایل ببر. در بعضی تم‌ها <code>+</code> فقط hover است. یا Palette → <code>Git: Stage Changes</code>.</p>\n</li>\n<li>\n<p><strong>یک کلیک داخل جعبهٔ Message</strong> و بنویس مثلاً <code>feat(auth): add JWT refresh flow</code>.<br />\n<strong>اگر جعبه غیرفعال است:</strong> هنوز Staged نداری و Smart Commit خاموش است — مرحلهٔ ۴ را بزن. یا فوکوس روی ادیتور است.</p>\n</li>\n<li>\n<p><strong><code>Ctrl+Enter</code></strong> (مک: <code>Cmd+Enter</code>) <strong>یا</strong> یک کلیک روی دکمهٔ <strong>Commit</strong>.<br />\n<strong>باید ببینی:</strong> لیست خالی می‌شود، دکمه ممکن است به Sync/Publish عوض شود، نوار وضعیت <code>↑1</code> بگیرد اگر remote داری.</p>\n</li>\n</ol>\n<p><strong>اگر کلیک Commit همهٔ فایل‌ها را برد نه فقط یکی:</strong> <code>git.enableSmartCommit</code> روشن است. Settings → این گزینه را Off کن. از این به بعد بدون Stage، دکمه Commit کار نمی‌کند یا هشدار می‌دهد.</p>\n<p><strong>اگر خطا Signing failed / secret key:</strong> فصل ۲ — امضا روشن است ولی کلید SSH signing روی این ماشین نیست. موقتاً <code>git.enableCommitSigning</code> را Off کن یا کلید را بساز.</p>\n<p><strong>اگر خطا Please tell me who you are:</strong> <code>user.name</code> و <code>user.email</code> ست نشده — فصل ۲.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📦 Staged در برابر Changes — دو کلیک معکوس</span></span></h2>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-staged-zoom.png\" alt=\"Staged Changes و Changes جدا\"/>\n<p class=\"figcap\">شکل ۱۰ب — بالا می‌رود داخل کامیت؛ پایین هنوز نمی‌رود. اگر فقط یک لیست می‌بینی، یا چیزی Stage نکرده‌ای یا Untracked جداست.</p>\n</div>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>می‌خواهی</th>\n<th>کلیک دقیق</th>\n<th>باید ببینی</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>فایل برود برای کامیت</td>\n<td><code>+</code> روی ردیف در Changes</td>\n<td>ردیف می‌پرد به عنوان <strong>Staged Changes</strong></td>\n</tr>\n<tr>\n<td>پشیمان از Stage</td>\n<td><code>-</code> روی ردیف در Staged</td>\n<td>برمی‌گردد به Changes؛ فایل روی دیسک همان است</td>\n</tr>\n<tr>\n<td>همه را Stage</td>\n<td><code>+</code> روی نوار عنوان <strong>Changes</strong> (نه روی فایل)</td>\n<td>همه می‌روند بالا</td>\n</tr>\n<tr>\n<td>تغییرات فایل روی دیسک دور ریخته شود</td>\n<td>راست‌کلیک روی ردیف Changes → <strong>Discard Changes</strong> → تأیید</td>\n<td>فایل از لیست می‌رود؛ محتوای ادیتور به نسخهٔ قبلی برمی‌گردد</td>\n</tr>\n</tbody>\n</table></div><p><strong>اگر Staged Changes را به‌عنوان عنوان جدا نمی‌بینی:</strong> هنوز <code>+</code> نزدی. با Smart Commit روشن، ممکن است بدون این عنوان هم Commit همه را بگیرد — برای همین خاموشش کردیم.</p>\n<p><strong>اگر Discard را زدی و فایل برگشت:</strong> Untracked (<code>U</code>) را Discard کردن یعنی حذف فایل از دیسک. VS Code معمولاً «Are you sure?» می‌پرسد. اگر پرسید و Yes گفتی، از Timeline برگردان (پایین فصل).</p>\n<p><strong>اگر Untrackedها ته یک لیست قاطی‌اند نه گروه جدا:</strong> Settings → <code>git.untrackedChanges</code> را بگذار <code>separate</code>.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔬 hunk — سه کلیک آبی روی خود diff</span></span></h2>\n<p class=\"keep-next\">hunk = چند خط سبز/قرمز پشت‌سرهم. معادل <code>git add -p</code>.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-hunk-zoom.png\" alt=\"Stage Selected Ranges روی diff\"/>\n<p class=\"figcap\">شکل ۱۰پ — این سه لینک آبی فقط وقتی فایل را از Changes باز کرده باشی بالای hunk ظاهر می‌شوند.</p>\n</div>\n<ol>\n<li>در Changes <strong>یک کلیک</strong> روی فایل.</li>\n<li>در diff، خطوطی که می‌خواهی را با ماوس رنگ کن (یا هیچی انتخاب نکن اگر کل hunk را می‌خواهی).</li>\n<li><strong>یک کلیک</strong> روی یکی از سه لینک آبی بالای hunk:\n<ul>\n<li><strong>Stage Change</strong> = کل این hunk</li>\n<li><strong>Stage Selected Ranges</strong> = فقط خطوط انتخاب‌شده</li>\n<li><strong>Discard Change</strong> = همین hunk از روی دیسک برگردد</li>\n</ul>\n</li>\n</ol>\n<p><strong>باید ببینی:</strong> اگر فقط بخشی Stage شد، فایل هم در Staged می‌ماند هم در Changes (حرف گاهی <code>M</code> دو جا). این درست است.</p>\n<p><strong>اگر لینک آبی نبود:</strong></p>\n<ul>\n<li>diff را از Timeline باز کرده‌ای نه از Changes — ببند، از Source Control روی فایل کلیک کن.</li>\n<li>روی نمای پیش‌نمایش Markdown هستی نه متن — روی تب فایل خام کلیک کن.</li>\n<li>تنظیم <code>diffEditor.renderSideBySide</code> فرق ندارد؛ لینک‌ها باید باشند. VS Code را به‌روز کن.</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">▾ فلش کنار Commit — یک کلیک، پنج فرمان</span></span></h2>\n<p class=\"keep-next\"><strong>یک کلیک روی فلش ▾ سمت راست دکمهٔ Commit</strong> (نه خود Commit).</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-commit-menu-zoom.png\" alt=\"منوی Commit در Source Control\"/>\n<p class=\"figcap\">شکل ۱۰ت — اگر فلش را نمی‌بینی، دکمه هنوز Commit نیست (Sync/Publish است) یا عرض ستون خیلی کم است؛ ستون را بکش عریض‌تر کن.</p>\n</div>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>کلیک روی</th>\n<th>چه می‌شود</th>\n<th>اگر مال تو خاکستری / نیست</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Commit</td>\n<td>فقط ثبت محلی</td>\n<td>باید Staged یا Smart Commit داشته باشی</td>\n</tr>\n<tr>\n<td>Commit &amp; Push</td>\n<td>ثبت + ارسال به origin</td>\n<td>origin نباشد → اول Publish Branch</td>\n</tr>\n<tr>\n<td>Commit &amp; Sync</td>\n<td>ثبت + pull/push</td>\n<td>tracking نداشته باشی، Push جدا بزن</td>\n</tr>\n<tr>\n<td>Undo Last Commit</td>\n<td>آخرین کامیت باز می‌شود، فایل‌ها Staged می‌مانند</td>\n<td>کامیت نداری</td>\n</tr>\n<tr>\n<td>Amend</td>\n<td>آخرین کامیت را با Stage فعلی و پیام جدید عوض می‌کند</td>\n<td>بعد از push نزن</td>\n</tr>\n</tbody>\n</table></div><div class=\"callout callout-warn\"><div class=\"callout-title\">Amend بعد از push</div>\n<p>هش عوض می‌شود. اگر همکار آن کامیت را گرفته، تاریخچه دوپاره می‌شود.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">⌨️ میانبر وقتی فوکوس کجاست؟</span></span></h2>\n<p><code>Ctrl+Enter</code> فقط داخل جعبهٔ Message کامیت می‌زند. اگر فوکوس روی ادیتور باشد، ممکن است کار دیگری بکند یا هیچ.</p>\n<p class=\"keep-next\"><strong>یک کلیک داخل Message، بعد Ctrl+Enter.</strong> اگر عادت شد: بعد از Stage، کلیک Message، میانبر.</p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>کار</th>\n<th>کلیک / کلید</th>\n<th>شرط</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>باز کردن پنل</td>\n<td><code>Ctrl+Shift+G</code></td>\n<td>—</td>\n</tr>\n<tr>\n<td>کامیت</td>\n<td><code>Ctrl+Enter</code></td>\n<td>فوکوس روی Message</td>\n</tr>\n<tr>\n<td>Palette</td>\n<td><code>Ctrl+Shift+P</code> سپس <code>Git:</code></td>\n<td>—</td>\n</tr>\n<tr>\n<td>Diff</td>\n<td>Enter روی ردیف فایل</td>\n<td>فوکوس لیست Changes</td>\n</tr>\n<tr>\n<td>Stage همه</td>\n<td><code>Git: Stage All Changes</code></td>\n<td>—</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">🧵 Timeline — این یکی داخل Source Control نیست</span></span></h2>\n<p class=\"keep-next\"><strong>کلیک‌ها:</strong> آیکون Explorer بالا-چپ Activity Bar (دو سند) → فایل را در درخت انتخاب کن → پایین همان ستون تب <strong>Timeline</strong> را باز کن (اگر جمع است، عنوان Timeline را کلیک کن).</p>\n<div class=\"shot\">\n<img src=\"/book/figures/vscode-timeline.png\" alt=\"Timeline فایل در VS Code\"/>\n<p class=\"figcap\">شکل ۱۰ث — اگر Timeline خالی است، فایل را انتخاب نکرده‌ای یا Git در این پوشه نیست.</p>\n</div>\n<p><strong>یک کلیک روی یک ردیف Timeline</strong> آن نسخه را مقایسه می‌کند. Local History برای Discard فایل Untracked است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧪 تمرین — هر کدام را تا «باید ببینی» پیش برو</span></span></h2>\n<p><strong>تمرین ۱.</strong> پوشهٔ خالی Open Folder → باید Initialize ببینی → کلیک Initialize → <code>README.md</code> بساز و Save → باید U در Changes → <code>+</code> → Message <code>docs: add readme</code> → Ctrl+Enter → باید لیست خالی شود.</p>\n<p><strong>تمرین ۲.</strong> سه فایل را Save کن → فقط روی یکی <code>+</code> → Commit → باید دو فایل در Changes مانده باشد. اگر هر سه رفتند، Smart Commit را Off کن و تمرین را تکرار کن.</p>\n<p><strong>تمرین ۳.</strong> یک فایل را چند خط عوض کن → از Changes باز کن → فقط بعضی خط‌ها را Stage Selected Ranges بزن → باید فایل هم بالا هم پایین باشد.</p>\n<p><strong>تمرین ۴.</strong> Discard یک <code>M</code> → از Timeline برگردان.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — چرا Save کافی نیست؟</strong> Save فقط فایل روی دیسک را عوض می‌کند. تاریخچه با کلیک Commit ساخته می‌شود.</p>\n<p><strong>Mid — چرا مال من دکمه Commit است و در عکس Sync؟</strong> چون تو تغییر ذخیره‌شده داری و عکس کتاب Working Tree تمیز + origin جلوتر را نشان می‌دهد. دکمه بر اساس وضعیت عوض می‌شود.</p>\n<p><strong>Senior — Publish to GitHub دقیقاً بعد از چند کلیک چه می‌سازد؟</strong> ریپو، <code>origin</code>، و <code>push -u</code>. بدون Sign in، همان کلیک پنجرهٔ ورود باز می‌کند نه خطا.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>سه راه باز کردن پنل را بلدی و اگر باز نشد جدول بالا را بلدی</li>\n<li>از روی برچسب دکمهٔ بزرگ می‌گویی در کدام حالتی</li>\n<li>مسیر Save → کلیک فایل → <code>+</code> → Message → Ctrl+Enter را بدون حدس می‌روی</li>\n<li>اگر صفحه با عکس یکی نبود، ستون «چرا؟» را می‌دانی نه اینکه کتاب غلط است</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> همان پنل، سطح فوق‌پیشرفته — با همین قرارداد «کلیک / باید ببینی / اگر فرق داشت».</p></div>";
export default { n, num, title, label, part, html };
